sp_widget.client_script:
api.controller=function($scope){
    var c=this;

    c.search=function(){
        c.server.update();
    };

    c.clear=function(){
        $scope.page.searchText='';
        $scope.page.department='';
        $scope.page.status='';
        c.server.update();
    };
};

sp_widget.css:
.directory-filters{

display:flex;

gap:14px;

align-items:center;

padding:22px;

margin-top: 15px;
border:grey 1px solid;

position:relative;

z-index:10;

background:white;

border-radius:24px;

box-shadow:
0 18px 50px
rgba(13,35,94,.08);

}



/* INPUT */

.directory-filters input{

flex:1;

min-width:220px;

height:54px;

border:none;

background:#F5F7FD;

border-radius:18px;

padding:0 18px;

font-size:13px;

outline:none;

transition:.25s;

}


.directory-filters input:focus{

box-shadow:
0 0 0 3px
rgba(47,98,245,.12);

}



/* SELECT */

.directory-filters select{

width:240px;

height:54px;

border:none;

background:#F5F7FD;

border-radius:18px;

padding:0 18px;

font-size:13px;

outline:none;

cursor:pointer;

}



/* BUTTON */

.directory-filters button{

width:150px;

height:54px;

border:none;

border-radius:18px;

background:
linear-gradient(
90deg,
#24D3A1,
#41D4C5
);

color:white;

font-size:13px;

font-weight:800;

cursor:pointer;

transition:.25s;

}


.directory-filters button:hover{

transform:
translateY(-2px);

}



/* LAPTOP */

@media(max-width:1200px){

.directory-filters{

display:grid;

grid-template-columns:
1fr 1fr;

gap:14px;

}

.directory-filters input{

grid-column:
1 / -1;

}

.directory-filters select,
.directory-filters button{

width:100%;

}

}



/* TABLET */

@media(max-width:768px){

.directory-filters{

padding:18px;

margin-top:-20px;

grid-template-columns:
1fr;

}

.directory-filters input,
.directory-filters select,
.directory-filters button{

width:100%;

min-width:unset;

}

}



/* MOBILE */

@media(max-width:480px){

.directory-filters{

padding:16px;

border-radius:20px;

}

.directory-filters input,
.directory-filters select,
.directory-filters button{

height:48px;

font-size:12px;

}

}

sp_widget.script:
(function(){
    data.departments = [
        'Architecture',
        'Data & Analytics',
        'Design',
        'Engineering',
        'Human Resources',
        'Infrastructure',
        'Operations',
        'Product',
        'Quality',
        'Security'
    ];
    data.searchText = input && input.searchText || '';
    data.department  = input && input.department  || '';
    data.status      = input && input.status      || '';
})();
